"""Research loop. Running out of steps is a DIFFERENT outcome from finishing."""

import os

import anthropic

client = anthropic.Anthropic(api_key=os.environ["ANTHROPIC_API_KEY"])
MODEL = "claude-sonnet-4-5"
MAX_STEPS = 40


class StepBudgetExhausted(RuntimeError):
    """The loop ran out of steps. No answer was produced."""


def run(question: str, strict: bool = True) -> dict:
    messages = [{"role": "user", "content": question}]
    latest = ""
    for _ in range(MAX_STEPS):
        reply = client.messages.create(
            model=MODEL, max_tokens=2048, messages=messages
        )
        latest = reply.content[0].text
        messages.append({"role": "assistant", "content": latest})
        if latest.startswith("FINAL:"):
            return {"outcome": "finished", "answer": latest.removeprefix("FINAL:").strip()}
        messages.append({"role": "user", "content": "Continue."})
    if strict:
        raise StepBudgetExhausted(f"no answer after {MAX_STEPS} steps")
    # Non-strict callers still get a terminal status they can branch on, and the
    # partial text is labelled so no driver can read it as a completed answer.
    return {"outcome": "exhausted", "partial": latest, "answer": None}
